// Parse the LLM response
const response = $input.first().json;
const title = $('User Story Form').first().json['User Story Title'];

let content = '';
try {
  content = response.choices[0].message.content;
} catch (e) {
  return [{ json: { resultText: '<h2>Error</h2><p>No response from the LLM. Check the API key.</p>' } }];
}

// Clean and parse JSON
let cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
let evaluation;
try {
  evaluation = JSON.parse(cleaned);
} catch (e) {
  return [{ json: { resultText: '<h2>Parsing error</h2><p>The LLM did not return valid JSON:</p><pre>' + cleaned.substring(0, 500) + '</pre>' } }];
}

// Choose verdict emoji and colour
let emoji = '⚠️';
let colour = '#f59e0b';
if (evaluation.verdict === 'OK') { emoji = '✅'; colour = '#22c55e'; }
else if (evaluation.verdict === 'BLOCKING') { emoji = '🔴'; colour = '#ef4444'; }

// Build the details table
const rows = Object.entries(evaluation.details || {})
  .map(([criterion, val]) => {
    const barWidth = (val.score / 2) * 100;
    return `<tr>
      <td style="padding:8px 12px;font-weight:600;text-transform:capitalize;">${criterion.replace('_', ' ')}</td>
      <td style="padding:8px 12px;text-align:center;"><strong>${val.score}/2</strong></td>
      <td style="padding:8px 12px;">
        <div style="background:#e5e7eb;border-radius:4px;height:8px;width:100px;">
          <div style="background:${colour};border-radius:4px;height:8px;width:${barWidth}px;"></div>
        </div>
      </td>
      <td style="padding:8px 12px;color:#555;">${val.comment}</td>
    </tr>`;
  }).join('');

const suggestions = (evaluation.suggestions || [])
  .map(s => `<li style="margin-bottom:4px;">${s}</li>`)
  .join('');

const html = `
<div style="font-family:system-ui,sans-serif;max-width:700px;margin:0 auto;">
  <h2 style="margin-bottom:4px;">${emoji} Assessment: ${title}</h2>
  <p style="font-size:1.3em;color:${colour};font-weight:700;">Score: ${evaluation.score_total}/10 — ${evaluation.verdict}</p>
  <table style="width:100%;border-collapse:collapse;margin:16px 0;">
    <thead>
      <tr style="background:#f3f4f6;">
        <th style="padding:8px 12px;text-align:left;">Criterion</th>
        <th style="padding:8px 12px;">Score</th>
        <th style="padding:8px 12px;">Bar</th>
        <th style="padding:8px 12px;text-align:left;">Comment</th>
      </tr>
    </thead>
    <tbody>${rows}</tbody>
  </table>
  ${suggestions.length > 0 ? '<h3>Suggestions</h3><ul>' + suggestions + '</ul>' : ''}
</div>
`;

return [{ json: { resultText: html } }];
